import{_ as l,l as r,o as e,c as s,v as t,p as h,x as i,d as n,i as p,S as C}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"SOCS 分解","description":"","frontmatter":{"title":"SOCS 分解","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/socs-decomposition.md","filePath":"litho/socs-decomposition.md","lastUpdated":1789023840000}'),d={name:"litho/socs-decomposition.md"};function m(_,a,f,b,c,S){const o=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="socs-分解" tabindex="-1">SOCS 分解 <a class="header-anchor" href="#socs-分解" aria-label="Permalink to &quot;SOCS 分解&quot;">​</a></h1><div class="epigraph"><p>四维 TCC 是厄米核；本征展开把它写成少数相干系统的强度和。截断的是数值秩，不是另一套成像原理。</p><footer>—— Hopkins 核的本征分解；光刻上的和差相干（SOCS）见 Cobb 的模型基 OPC 表述，以及 Pati &amp; Kailath 对双线性核 SVD 的光学讨论</footer></div><p><a href="/litho/abbe-vs-hopkins">上一课</a>对照了扫源与预计算 TCC。缺口是：四维核直接往全芯片上套太重，主干 Hopkins 课只点到「可以本征展开」，还没有把**和差相干系统（SOCS）**写成可调用的接口。本课钉分解与截断。时间 / 空间相干的物理差别留给<a href="/litho/temporal-spatial-coherence">下一课</a>。不重推 \\(k_1\\)，不引用未公开的引擎缺省秩。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>空中像 \\(I=\\iint T(\\mathbf{f}_1)T^*(\\mathbf{f}_2)\\,\\mathrm{TCC}(\\mathbf{f}_1,\\mathbf{f}_2)\\,e^{2\\pi i(\\mathbf{f}_1-\\mathbf{f}_2)\\cdot\\mathbf{x}}\\,d^2\\mathbf{f}_1 d^2\\mathbf{f}_2\\)。把 TCC 看成对 \\((\\mathbf{f}_1,\\mathbf{f}_2)\\) 的厄米核，存在本征系统 \\(\\{\\phi_k,\\lambda_k\\}\\)，使得</p> \\[I(\\mathbf{x})=\\sum_k\\lambda_k\\bigl|(t*\\phi_k)(\\mathbf{x})\\bigr|^2 \\]<p>（空域写法：每只 \\(\\phi_k\\) 是一个相干核，\\(\\lambda_k\\ge 0\\) 为权重）。这就是 SOCS：Sum of Coherent Systems。缺口因此是把上一课的核变成<strong>可截断的相干通道和</strong>，而不是再扫一遍源点。</p><p>完全相干：秩 1，回到单只 PSF。完全非相干：秩高，通道多。部分相干通常只要数十个主通道就能让空中像误差落到 OPC 可接受的范围——这是计算事实，不是新的衍射理论。</p><h3 id="截断是误差预算" tabindex="-1">截断是误差预算 <a class="header-anchor" href="#截断是误差预算" aria-label="Permalink to &quot;截断是误差预算&quot;">​</a></h3><p>丢掉小 \\(\\lambda_k\\) 等于丢掉弱相干通道。误差在开阔区、大位移交叉项上往往更可见。报「用了 SOCS」必须声明保留几阶、误差范数怎么验，不能把秩写成物理 \\(\\sigma\\)。换照明或换镜头指纹，本征系统全换；旧核的前几阶不能继承。</p><p><span class="marginnote">Pati &amp; Kailath (JOSA A, 1994) 从双线性成像写 SVD；Cobb 把它接到全芯片碎片求值。本课要的是接口：强度是加权相干像之和。GPU 与稀疏网格是工程，不是定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数值上把离散 TCC 做成矩阵（或用源点积分构造等价算子），求前 \\(K\\) 个本征对。每个 \\(\\phi_k\\) 与物体做一次卷积（或 FFT 乘），模方加权相加。这比 Abbe 扫成百上千源点通常更省，因为 \\(K\\ll N_s\\) 在平滑照明下成立；环形、多极照明的有效秩会升高。</p><p>等晕假设：一场点一副核。扫描狭缝上镜头指纹随场变，则 \\(K\\) 套核随场插值，不是「全场一张 SOCS」。矢量 TCC：每个偏振块分别分解，或拼成更大的核再分解——通道数再乘，定义不变。</p>',14)),(e(),h(C,null,{default:i(()=>[p(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20TCC%5B%22TCC(f1%2C%20f2)%22%5D%20--%3E%20EIG%5B%22%E6%9C%AC%E5%BE%81%E5%AF%B9%20%CE%BBk%2C%20%CF%86k%22%5D%0A%20%20EIG%20--%3E%20SUM%5B%22I%20%3D%20%CE%A3%20%CE%BBk%20%7Ct%20*%20%CF%86k%7C%C2%B2%22%5D%0A%20%20K%5B%22%E6%88%AA%E6%96%AD%20K%22%5D%20--%3E%20ERR%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20SUM%20--%3E%20ERR%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="与傅里叶骨架的关系" tabindex="-1">与傅里叶骨架的关系 <a class="header-anchor" href="#与傅里叶骨架的关系" aria-label="Permalink to &quot;与傅里叶骨架的关系&quot;">​</a></h3><p>每一通道仍是<a href="/litho/fourier-pairs-convolution">第一课</a>的卷积。SOCS 没有引入新的变换对，只是把部分相干的切片基底从「源点」换成「TCC 的本征函数」。源点基底不正交；本征基底按能量排序，所以能截。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TCC 的平滑来自光瞳与源都是有限支撑的积分核，故奇异值衰减。衰减快，低秩好用；源上细节多（极细偶极、像素化 SMO），衰减慢，Abbe 或更高 \\(K\\) 更合适。这就是上一课「何时扫源、何时预计算」在秩语言里的答案。</p><p>OPC 每动一条边，只需用同一组 \\(\\phi_k\\) 更新局部卷积，不必重分解——前提是照明与 \\(P\\) 没变。这是模型基 OPC 能全芯片迭代的光学理由之一，规则表做不到这一点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>SOCS 是薄物体、等晕、Hopkins 框架内的算法。掩模 3D 让 \\(T\\) 依赖入射角，严格分解对物体不独立；实践用域分解或 Abbe。胶模糊是额外卷积，可乘在通道上，不是 TCC 的本征值。禁止把某代计算光刻软件的默认 \\(K\\) 写成物理常数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SOCS：TCC 本征展开，强度为加权相干像之和。</li><li>截断 \\(K\\) 是数值误差，换照明必须重分解。</li><li>每通道仍是傅里叶卷积骨架。</li><li>矢量与场相关只增加核的套数。</li><li>下一课：通道背后的时间相干与空间相干。</li><li>出处：Hopkins (1953)；Pati &amp; Kailath, <em>JOSA A</em> (1994)；Cobb 对 SOCS / 模型 OPC 的表述。</li></ul>',9))])}const u=l(d,[["render",m]]);export{T as __pageData,u as default};
